# Reproducible findings and checks that could materially change the conclusions.
library(dplyr)
library(readr)
field <- read_csv("data/derived/field_observations.csv", show_col_types = FALSE)
nights <- read_csv("data/derived/reef_nights.csv", show_col_types = FALSE)
weights <- read_csv("outputs/tables/07_weighting_summary.csv", show_col_types = FALSE)
hero <- read_csv("outputs/tables/05_one_reef_one_night.csv", show_col_types = FALSE)
sst <- read_csv("data/derived/sst_daily.csv", show_col_types = FALSE)
sst_events <- read_csv("data/derived/sst_events.csv", show_col_types = FALSE)
lunar <- read_csv("outputs/tables/03_lunar_calendars.csv", show_col_types = FALSE)
seasons <- read_csv("outputs/tables/02_seasonal_calendars.csv", show_col_types = FALSE)

# Integrity checks supplement the explicit many-to-one checks in import.
stopifnot(!anyDuplicated(paste(sst$subsite_id, sst$date)),
          !anyNA(sst_events$sst_c),
          all(abs((lunar |> summarise(s = sum(share), .by = label))$s - 1) < 1e-10),
          all(abs((seasons |> summarise(s = sum(share), .by = label))$s - 1) < 1e-10))
dawn <- field |> filter(Obs_ID %in% c(3975, 3976))
stopifnot(nrow(dawn) == 2, all(dawn$sunset_offset_hours < -12),
          all(field$midnight_ambiguous[field$Obs_ID == 6153]))
quality <- read_csv("data/derived/data_quality.csv", show_col_types = FALSE)
write_csv(quality, "outputs/tables/data_quality.csv")

percent <- function(x) sprintf("%.1f%%", 100 * x)
moon_file <- "data/derived/lunar_audit.csv"
moon_text <- "No independently matched lunar events were available; source-derived lunar offsets are used in the figures."
if (file.exists(moon_file)) {
  audit <- read_csv(moon_file, show_col_types = FALSE)
  moon_text <- sprintf("Independent USNO cross-check: %s recorded reef-nights covered; %s agree exactly with supplied offsets. This is limited to the cached response coverage, not validation of all years.",
                       nrow(audit), sum(audit$difference_days == 0))
}
findings <- c(
  "# The Ocean's Clock — findings and interpretation", "",
  "This document is generated by R/07_results.R from the exported analytical tables.", "",
  "## The data we can actually speak about", "",
  sprintf("The relational joins retain all 6,178 source observations. The natural-reef subset contains %s rows, representing %s subsite-dates across %s named sites and %s subsites. These are recorded occurrences with unknown survey effort, not a random sample of reefs or nights.",
          format(nrow(field), big.mark = ","), format(nrow(nights), big.mark = ","), n_distinct(nights$site), n_distinct(nights$subsite_id)), "",
  "## 1. Place and season", "",
  "The atlas reveals uneven coverage. The seasonal calendar shows recorded events concentrated in different months at different sites. Both biological differences and observation schedules can contribute. A zero cell means no recorded event, not a proven non-spawning month.", "",
  "## 2. The Moon and a fairer count", "",
  paste(sprintf("- %s: **%s** of recorded events fall on days 0–7 after the nearest local full moon.", weights$method, percent(weights$share)), collapse = "\n"), "",
  "The lunar concentration remains under all three weighting choices. Its magnitude depends materially on how repeatedly documented nights and sites count. This descriptive window was not a preregistered hypothesis and is not a forecast or causal estimate.", "",
  "## 3. A nightly schedule, with exceptions", "",
  "Most displayed genera have their median exact starting time after sunset; Pocillopora in this sample is a morning-spawning exception. The pooled genus comparisons differ in sites, species and coverage, so they cannot isolate a genus effect. Start-quality filtering and collapsing repeated species rows are essential.", "",
  sprintf("At a single Orpheus Island subsite on 24 November 1983, %s species have exact recorded starts ranging from %.2f to %.2f hours after sunset. Shared night does not mean identical minute. This case was deliberately selected for its informative coverage, not as a representative random night.",
          nrow(hero), min(hero$first_start), max(hero$last_start)), "",
  "## 4. Connecting the ocean context", "",
  sprintf("The 2016 temperature case study contains %s exact date-matched spawning reef-nights and %s NOAA point extractions across %s selected subsites and 21 sampled dates. Within each of three named sites, one subsite is selected by its number of recorded 2016 reef-nights (tie: smallest ID). The reference curve connects first-of-month samples; it is not a full daily time series or climate normal.",
          nrow(sst_events), format(nrow(sst), big.mark = ","), n_distinct(sst$subsite_id)), "",
  "The combined calendar places season, lunar timing and temperature in one view. Different local thermal cycles provide context; the graphics do not identify a universal temperature threshold or show that temperature caused a timing change. Biological composition and observation schedules differ between sites. All temperature case-study observations are from 2016. NOAA surface-grid values are not coral-depth measurements. A daily UTC grid-date is matched to a recorded local date; this is a daily-date approximation, not an exact local-time ocean measurement.", "",
  "## Independent reference check", "", moon_text, "",
  "Source full-moon offsets remain the primary lunar measure; independent checks do not create a new predictor. The midnight and local-date examples are documented in docs/LEARNING_GUIDE.md and the source/audit tables.", "",
  "## What makes the work substantive", "",
  "Separate relational tables; many-to-one key checks; explicit field/ex-situ and start-quality separation; three counting units; independent astronomy coverage reported honestly; coordinate-and-date temperature joins; sensitivity to uneven sampling; genuine dawn events preserved; cached public inputs; reproducible PNGs and their plot-data tables.", "",
  "## Remaining submission responsibilities", "",
  "Confirm the two-person exception (published brief: 3–5), Prezi instead of the stated PowerPoint format, and any later jury rubric/report instructions. Record actual individual contributions and assign main-author names before final submission exports. Attendance, participation, oral explanation and Moodle upload remain student responsibilities. No slides or website are generated by this project.")
writeLines(findings, "outputs/RESULTS.md", useBytes = TRUE)
message("Meaningful data and timing checks passed.")
